function fieldTip(f) {
    if (!f || !f.key) return '';
    return f.tip || FIELD_TIPS[`${f.key}|${f.label}`] || FIELD_TIPS[f.key] || '';
}

// Label HTML for hand-built inputs (import review): underlined with its tip when one exists
function tipLabelHtml(key, label) {
    const tip = FIELD_TIPS[`${key}|${label}`] || FIELD_TIPS[key];
    if (!tip) return label;
    const attr = tip.replace(/&/g, '&amp;').replace(/"/g, '&quot;').replace(/</g, '&lt;');
    return `<span class="has-tip" tabindex="0" data-tip="${attr}">${label}</span>`;
}

// One tooltip element on <body>, positioned fixed so modal and table scroll areas never clip it.
// Delegated listeners: forms and grids rebuild their labels on every render.
(function () {
    let tipEl = null;
    let current = null;

    function show(target) {
        const text = target.getAttribute('data-tip');
        if (!text) return;
        if (!tipEl) {
            tipEl = document.createElement('div');
            tipEl.className = 'field-tip';
            tipEl.setAttribute('role', 'tooltip');
            tipEl.id = 'fieldTip';
            document.body.appendChild(tipEl);
        }
        current = target;
        tipEl.textContent = text;
        tipEl.style.display = 'block';
        target.setAttribute('aria-describedby', 'fieldTip');
        const r = target.getBoundingClientRect();
        const t = tipEl.getBoundingClientRect();
        const left = Math.max(8, Math.min(r.left, window.innerWidth - t.width - 8));
        const below = r.bottom + 6;
        const top = below + t.height > window.innerHeight - 8 ? r.top - t.height - 6 : below;
        tipEl.style.left = `${left}px`;
        tipEl.style.top = `${Math.max(8, top)}px`;
    }

    function hide() {
        if (current) current.removeAttribute('aria-describedby');
        current = null;
        if (tipEl) tipEl.style.display = 'none';
    }

    document.addEventListener('mouseover', (e) => {
        const target = e.target.closest?.('[data-tip]');
        if (target && target !== current) show(target);
        else if (!target && current) hide();
    });
    document.addEventListener('focusin', (e) => {
        const target = e.target.closest?.('[data-tip]');
        if (target) show(target);
    });
    document.addEventListener('focusout', hide);
    document.addEventListener('scroll', hide, true);
    document.addEventListener('keydown', (e) => { if (e.key === 'Escape') hide(); });
})();
